-- =============================================================================
-- V1 · 接收台账 schema 与索引
-- =============================================================================
--  本脚本同时被 PostgreSQL（生产）与 H2 PG 兼容模式（测试）执行，**不允许分叉**。
--  兼容性约束：
--    1. 不使用 PostgreSQL 专有类型（如 JSONB、UUID、ARRAY）或专有函数
--    2. 不使用 H2 专有语法或非标准 SQL（如 MySQL 的 `AUTO_INCREMENT`）
--    3. 时间戳统一用 TIMESTAMP（不带时区），由应用层负责对端时区归一
--    4. 主键统一用 BIGINT 标识列 + GENERATED BY DEFAULT AS IDENTITY
--       —— 这是 SQL 标准语法，PG 12+/H2 2.x 均支持；比 SERIAL 更可移植
--    5. 字符串类型统一用 VARCHAR(N)，不混 TEXT/CLOB
--    6. 约束命名与索引命名在两库下都生效（不用 IF NOT EXISTS 之类方言）
--
--  幂等键（MSH-9 + MSH-10 + MSH-11）三列共同作为业务主键的代理，唯一约束
--  uk_ledger_idem_key 在两库下表现一致：违反时抛 SQLException（PG 23505 / H2 23502-7），
--  业务层在 T13 的 JdbcLedgerStore.insertIfAbsent 把这个 SQLState 翻译成 AlreadyProcessed。
-- =============================================================================

-- message_ledger：一行 = 一条入站报文及其当前应用级状态
CREATE TABLE message_ledger (
    -- 主键：业务无关、自增。幂等键由 uk_ledger_idem_key 单独管。
    id                          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,

    -- 幂等键三段：消息类型 MSH-9、控制号 MSH-10、处理 ID MSH-11。
    -- 任一段留空也要占一行（缺 MSH-10 的报文也是一条独立报文），故非空约束只到 VARCHAR(1)，
    -- 不允许 NULL（NULL 进了唯一约束会被 PG 当「未指定」而破坏唯一性）。
    message_type                VARCHAR(64)  NOT NULL,
    control_id                  VARCHAR(64)  NOT NULL,
    processing_id               VARCHAR(64)  NOT NULL,

    -- 接入批次号：区域平台推一次包就是一个 batch；同 batch 内 re-delivery 与原投合并对账。
    batch_id                    VARCHAR(64)  NOT NULL,

    -- 当前应用级状态：字符串形式存储，定义在 ledger/MessageState，与 Java 枚举一一对应。
    -- 写入前由 MessageStateMachine.assertTransition 校验，不允许绕过状态机写库。
    state                       VARCHAR(32)  NOT NULL,

    -- 原始 HL7 v2 报文：缺省上限 1MB（T14 容量边界用例断言超长截断并告警），
    -- 实际数据库允许扩展到 4MB（32-bit N 长度），超 4MB 在应用层就拒不入库。
    raw_payload                 VARCHAR(1048576) NOT NULL,

    -- 院内患者主索引主键：写 HIS 患者主索引成功（T31）才填；
    -- 缺省空串表示「这条还没走到写入 HIS 的入口」。
    -- **绝不**与区域平台患者标识（PID-3）混用 —— 这是 spec.md 锁定的两条主键分离。
    local_mrn                   VARCHAR(64)  NOT NULL DEFAULT '',

    -- 模型降级标记：true = 该条因模型不可达而走降级路径（spec.md 锁定的边界）。
    degraded                    BOOLEAN      NOT NULL DEFAULT FALSE,

    -- 重投次数：每次进入 redelivery 入队 / 出队都递增；上限在 T33 控制。
    retry_count                 INTEGER      NOT NULL DEFAULT 0,

    -- 审计三件套：
    --   created_at  -- 入库时间
    --   updated_at  -- 最近一次状态迁移时间（重投也算）
    --   version     -- 乐观锁（与 T15 的 IdempotencyGuard / OptimisticLock 配套）
    created_at                  TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at                  TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    version                     BIGINT       NOT NULL DEFAULT 0,

    CONSTRAINT uk_ledger_idem_key UNIQUE (message_type, control_id, processing_id)
);

-- 按批次 + 状态查：「今天上午这条包有 2 条待确认」是高频运维问句，必须走索引。
-- 单列 batch_id 上的索引会被这组 (batch_id, state) 覆盖，节省一份。
CREATE INDEX idx_ledger_batch_state ON message_ledger (batch_id, state);

-- 状态 + 时间排序：「上次更新 > 24h 仍停在 PENDING_RETRY 的」是 T35 重启续跑的入口查询。
-- 该索引同样服务于 T19 的 BatchStats 与 T40 的 CapacityMetrics。
CREATE INDEX idx_ledger_state_updated ON message_ledger (state, updated_at);


-- message_audit：状态迁移的逐条审计痕，与 message_ledger 一对多。
-- 一条报文从入站到 LANDED 至少产生 2 行（入站 RECEIVED → PENDING_CONFIRM → LANDED），
-- 因此 ledger_id 上必须有索引。
CREATE TABLE message_audit (
    id                          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,

    -- 关联到 message_ledger.id；不建外键约束（让 T43 cleanup 可整库删除不留依赖），
    -- 但应用层在 transition 时保证一致性：未先有 ledger 行就不能有 audit 行。
    ledger_id                   BIGINT       NOT NULL,

    -- from_state / to_state 用 VARCHAR 而非外键到 message_ledger.state：
    -- 历史状态可能已被合法边删除（虽然本产品目前不会，但留出空间）。
    from_state                  VARCHAR(32)  NOT NULL,
    to_state                    VARCHAR(32)  NOT NULL,

    -- 操作人：T30 的 ConfirmGate 调用者、T33 的人工放行、T17 的撤回等动作的来源。
    -- 'system' 标识自动迁移（拆帧落库、状态机推进入站）；人名 / token subject 占其他取值。
    operator                    VARCHAR(64)  NOT NULL,

    -- 原因短语：例如 'revert'、'idempotent-replay'、'manual-release'、
    -- 'confirm'。自由文本，但写库前会在 T40 obs/RedactedLog 走脱敏检查。
    reason                      VARCHAR(256) NOT NULL,

    at                          TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX idx_audit_ledger_id_at ON message_audit (ledger_id, at);
CREATE INDEX idx_audit_to_state_at  ON message_audit (to_state, at);

-- schema_version：迁移自身记录。允许 LedgerSchema.version() 在启动后读出当前 schema 版本号，
-- 进入启动摘要。空表时 version() 返回空串（即「尚未迁移」）。
CREATE TABLE schema_version (
    version                    VARCHAR(32) PRIMARY KEY,
    applied_at                 TIMESTAMP  NOT NULL DEFAULT CURRENT_TIMESTAMP,
    notes                      VARCHAR(256) NOT NULL DEFAULT ''
);

-- V1 自登记：迁移成功后立即写一行。
INSERT INTO schema_version (version, notes) VALUES ('V1', '初始 schema：message_ledger + message_audit + 两组索引');
